def mark_cases_unsupported(testCase, caseNames, why):
    """Mark LATER cases UNSUPPORTED before they run, from the case that has just learned why.

    A case that finds out inside its own main() that it does not apply costs a power cycle of
    every device on the bench: the framework re-arms powerCycleOnFail before each case and
    cycles on any result but PASS. The TestSet runs a case only while its `supported` is True,
    so a case marked here is not run at all - no configure, main or tear_down, no cycle - and
    its class's `skipIfExcl = True` does the same under -u. Each marked case keeps its own check
    in main() for a run where this case did not run first (--include-test-cases, run-priority
    sampling). Module-level on purpose: the frame's lint reads every `self.testSet.<name>` as a
    device handle init() must bind.
    """
    wanted = set(caseNames)
    for tc in testCase.testSet.testCaseList:
        name = type(tc).__name__
        if name in wanted and tc.supported and not getattr(tc, 'hasBeenRun', False):
            tc.supported = False
            testCase.log('INFO: {} marked unsupported before it runs: {}'.format(name, why))


def publish_value(testCase, name, value):
    """Publish a value a later case reads: `testCase.testSet.<name> = value`.

    `None` means this case could not establish it, so every later case whose class lists
    `name` in its `ckNeeds` cannot run either: those are marked UNSUPPORTED before they run.
    """
    setattr(testCase.testSet, name, value)
    if value is None:
        mark_cases_unsupported(
            testCase, [type(tc).__name__ for tc in testCase.testSet.testCaseList
                       if name in getattr(type(tc), 'ckNeeds', ())],
            '{} was not established by {}'.format(name, type(testCase).__name__))


class TestSet(ATTestSet.TestSet):

    FEATURES = ['ALL']
    def _ck_discover(self, dut, unit=None):
        """Every data link on the DUT, classified by asking the DUT what is fitted in each port.

        `dut` is the switch handle commands go to; `unit` is what owns the ports — the STACK
        when the DUT is in one (its members' [portlink]s all count), else `dut` itself.

        Fixed frame — do not edit or delete. Nothing here is pre-declared (Terrence, 2026-09-21:
        "the information shouldn't require pre-loading variables to know it"). The cables come
        from the bench's own [portlink] section through `get_all_port_links()`; the testbox is
        the far end that is a TestBox; a member of the DUT's own stack is never a partner; and
        the MEDIA of each DUT-side port is read from `show interface <port> status` (its Type
        column) and `show system pluggable` (which cages hold a module). An EMPTY cage has no
        media and is no role — nothing is in it.
        Returns {bucket: [(near_port, far_port, far_device), ...]} for the buckets
        tb / copper (fixed twisted pair) / cusfp (twisted pair in a cage) / fibre / absent / unknown.
        """
        import ck_media
        unit = unit if unit is not None else dut
        members = set(unit.all_members()) if hasattr(unit, 'all_members') else set()
        in_cage = ck_media.pluggable_ports(dut.cmd('show system pluggable'))
        found = {'tb': [], 'copper': [], 'cusfp': [], 'fibre': [], 'absent': [], 'unknown': []}
        for far, pairs in unit.get_all_port_links().items():
            if far in members:
                continue                       # stackport / member cabling is not a data path
            for near, far_port in pairs:
                if isinstance(far, ATTestBox.TestBox):
                    found['tb'].append((near, far_port, far))
                    continue
                if not near.name.startswith('port'):
                    continue                   # an eth0 management link is not a data path
                status = dut.cmd('show interface %s status' % near.name)
                kind = ck_media.classify(ck_media.media_type(status, near.name))
                if kind == ck_media.TWISTED_PAIR:
                    bucket = 'cusfp' if ck_media.is_pluggable(near.name, in_cage) else 'copper'
                elif kind == ck_media.FIBRE:
                    bucket = 'fibre'
                elif kind == ck_media.ABSENT:
                    bucket = 'absent'
                else:
                    bucket = 'unknown'
                found[bucket].append((near, far_port, far))
        # Deterministic order, aggregator members LAST (tb470 sentinel, 2026-09-29):
        # get_all_port_links() walks Stack.members, a SET, so the same bench handed out a
        # different port run to run; and a port in a static-channel-group / channel-group is
        # an aggregator member, where a speed/duplex change on ONE member is an aggregator
        # artefact. Not skipped (the DUT decides; the tester may take the link out of its
        # aggregator for the run) - preferred against, and named in the log and at binding.
        self._ck_lag_ports = set()
        for v in found.values():
            for near, far_port, far in v:
                if near.name.startswith('port') and re.search(
                        r'^\s*(static-)?channel-group\b',
                        dut.cmd('show running-config interface %s' % near.name), re.M):
                    self._ck_lag_ports.add(near.name)

        def _natural(s):
            return [int(t) if t.isdigit() else t for t in re.split(r'(\d+)', s)]

        def _order(link):
            near, far_port, far = link
            return (near.name in self._ck_lag_ports, _natural(near.name),
                    _natural(getattr(far, 'name', 'tb')), _natural(far_port.name))
        for v in found.values():
            v.sort(key=_order)
        self.log('topology discovered on %s: %s' % (dut.name, '; '.join(
            '%s=%s' % (k, ','.join('%s%s<->%s.%s' % (
                n.name, ' [LAG member]' if n.name in self._ck_lag_ports else '',
                getattr(f, 'name', 'tb'), p.name) for n, p, f in v))
            for k, v in found.items() if v) or 'NO data links declared'))
        return found

    def _ck_bind_link(self, setup, dut, role, optional=False):
        """Take ONE discovered link for `role` and bind it: (near_port, far_port, far_device).

        Fixed frame — do not edit or delete. `role` is what the TEST needs — 'tb', 'copper',
        'fibre', 'cusfp' — and the link is whichever discovered cable carries that media, so
        the same script binds on any bench cabled for it while the bench declares nothing
        beyond its [portlink]s. A link is never handed out twice; a copper role takes a copper
        SFP only when no fixed twisted-pair link is left; a partner switch is initialised once
        however many links go to it. A REQUIRED role with no link aborts the suite — "this
        bench cannot host this test" is a bench problem, not a test result. An OPTIONAL
        (pluggable) role returns (None, None, None) and the cases needing it report UNSUPPORTED.
        """
        import ck_media
        buckets = {'tb': ('tb',), 'copper': ('copper', 'cusfp'),
                   'cusfp': ('cusfp',), 'fibre': ('fibre',)}[role]
        for bucket in buckets:
            if not self._ck_topo.get(bucket):
                continue
            near, far_port, far = self._ck_topo[bucket].pop(0)
            if isinstance(far, ATTestBox.TestBox):
                # The testbox end of a data link: any fitted media serves a capture/inject
                # path, but an EMPTY cage on the DUT side is a bench problem — say so now.
                status = dut.cmd('show interface %s status' % near.name)
                ok, why = ck_media.assert_role_media(status, near.name, 'tb')
                if not ok:
                    raise RuntimeError(why)
            else:
                # `far` is the device init_all_devices() already initialised — re-initialising
                # it would build a second object (init_stk) or abort the run (init_tb).
                self._ck_far.setdefault(far.name, far)
                far = self._ck_far[far.name]
            self.log('topology: role %r -> %s %s <-> %s %s (%s)' % (
                role, dut.name, near.name, getattr(far, 'name', 'tb'), far_port.name, bucket))
            if near.name in getattr(self, '_ck_lag_ports', ()):
                self.log('WARNING: %s %s is an aggregator member (channel-group in its running-config): '
                         'a speed/duplex change on ONE member is an aggregator artefact, not a port '
                         'result - take it out of the aggregator for the run, or cable a standalone '
                         'link, before trusting this role' % (dut.name, near.name))
            return near, far_port, far
        have = ', '.join('%d %s' % (len(v), k) for k, v in self._ck_topo.items() if v) or 'none'
        why = ("BENCH PROBLEM, not a product defect: no unused %s link on %s (data links "
               "discovered: %s). Cable a %s partner port to the DUT and declare it under "
               "[portlink]." % (role, dut.name, have, role))
        if optional:
            self.log(why + ' This role is OPTIONAL here: the cases needing it report UNSUPPORTED.')
            return None, None, None
        raise RuntimeError(why)


    def init(self, setup):
        # Topology is DISCOVERED through the framework at run time, never declared to this
        # script: the DUT is the framework's `swi_a` slot (its stack, when it is in one), the
        # partners are whatever the bench's [portlink]s cable to it, and which link is copper
        # / fibre / copper-SFP is read from the DUT itself. So the script names no port and no
        # partner, binds correctly on any bench cabled for it, and fails loudly on one that is
        # not. (`swi_a`/`stk_a`: 297/192 corpus lookups; a role-named key appears 0 times.)
        # Every device and link the bench's .setup declares is initialised FIRST, by the
        # framework's own init_all_devices(): get_all_port_links() returns only INITIALISED links
        # and get_stack() is set only by init_stk, so a frame that bound swi_a alone discovered
        # NOTHING — its first hardware run, T33235 on tb470, 2026-09-25, aborted in init() with
        # "no unused copper link". powerOn=False: binding never switches a PDU outlet on (a
        # power-cycle test still has its power objects). tb and swi_a come from the returned
        # device table — init_tb() a second time exits the run.
        _devs = setup.init_all_devices(powerOn=False)
        tb = _devs['tb']
        dutA = _devs['swi_a']
        # ART's own shape (103 of 239 suites bind BOTH the stack and the swi_a switch):
        # the STACK owns the ports [portlink] declares per member and is what discovery walks;
        # COMMANDS go to the swi_a member handle, which has cmd()/mode() — the framework's Stack
        # class defines neither, and every VCStack member serves the stack-wide CLI. (2026-09-21
        # to 2026-09-23 the frame rebound `dutA` to the Stack, so every command died on a
        # stacked DUT; Terrence: "Copy what they do, because it works.")
        _stk = dutA.get_stack()
        dut_stack = _stk                   # initialised above; init_stk() again builds a second Stack
        self.tb = tb
        self.dutA = dutA
        self.dut_stack = dut_stack
        # Values a test case PUBLISHES for later cases (the sequence's `publishes`), through
        # publish_value(). Each is None until its producer sets it; publishing None marks every
        # case that lists it in `ckNeeds` UNSUPPORTED before that case runs.
        self.baselineArp = None  # set by TestCase_1: dict ip->(mac, interface, port, type): the global ARP table with 4 dynamic and 2 static entries
        self.baselineCount = None  # set by TestCase_1: int: the total number of rows in baselineArp
        self.vrfBaseline = None  # set by TestCase_8: dict scope('global'|'red'|'blue')->dict ip->(mac, interface, port, type): ARP tables before the VRF clears
        self._ck_far = {}
        self._ck_topo = self._ck_discover(dutA, dut_stack)
        # The TESTBOX data link: the ART shape `(dut.portA, tb.ethA)`. Captures, injected
        # frames and pings happen on `tb.ethA`; `dutA.portA` is the DUT port under test
        # at the other end of that cable. REQUIRED: a bench without it aborts here.
        (dutA.portA, tb.ethA, _tb) = self._ck_bind_link(setup, dutA, 'tb')
        # The NEIGHBOUR switch on a fixed twisted-pair link, REQUIRED: a partner to negotiate
        # against, a polarity to force, a neighbour table to read. Named `peer`, never `dut`:
        # in ART `dut` is the DUT's own stack handle, and a partner called `dut` made every
        # model read `dut.portA` as the DUT's port (T44297, 2026-09-07).
        (dutA.portPeer, peer_port, peer) = self._ck_bind_link(setup, dutA, 'copper')
        peer.portDut = peer_port
        self.peer = peer

    def configure(self):
        tb = self.tb
        dutA = self.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        # One-time SUITE setup, runs ONCE before all test cases. Config only — no pass/fail.
        # setup: On the DUT, create test VLAN 10 and add the test port to it as a tagged trunk member. Create routed VLAN 20 on the source port as an untagged access member. Configure 'interface vlan10' / 'ip address 192.168.10.1/24' and 'interface vlan20' / 'ip address 192.168.20.1/24'.
        # setup: Configure two static ARP entries on the DUT in global configuration: 'arp 192.168.10.201 0000.5e00.5301 <test port>' and 'arp 192.168.10.202 0000.5e00.5302 <test port>'.
        # setup: On the traffic host attached to the test port, start Scapy ARP/ICMP responders on VLAN 10 for neighbours 192.168.10.11, .12, .13 and .14, each with its own unique MAC. On the traffic host attached to the source port, configure 192.168.20.100/24 with gateway 192.168.20.1. Start tcpdump on the test-port host interface, capturing ARP and IP.
        # setup: On the DUT, run 'ip vrf red' and 'ip vrf blue'. Create VLAN 30 and VLAN 40 and add them as tagged VLANs on the test port. On 'interface vlan30' apply 'ip vrf forwarding red' then 'ip address 192.168.30.1/24'. On 'interface vlan40' apply 'ip vrf forwarding blue' then 'ip address 192.168.40.1/24'. On the test-port host, start Scapy responders for 192.168.30.11–.12 (VLAN 30) and 192.168.40.11–.12 (VLAN 40), each with its own unique MAC.
        from threading import Thread

        dutA.mode(')#')
        dutA.cmd('vlan database')
        dutA.cmd('vlan 10,20,30,40 state enable')
        dutA.cmd('exit')
        dutA.mode(')#')
        dutA.cmd('ip vrf red')
        dutA.cmd('ip vrf blue')

        # test port: tagged trunk member of VLANs 10, 30 and 40
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('switchport mode trunk')
        dutA.cmd('switchport trunk allowed vlan add 10,30,40')

        # routed VLAN 20 on the second (source) port: untagged access member.
        # The bench binds no second testbox port, so the DUT's neighbour-link port is used for it.
        dutA.cmd('interface {}'.format(portPeer.name))
        dutA.cmd('switchport mode access')
        dutA.cmd('switchport access vlan 20')

        dutA.cmd('interface vlan10')
        dutA.cmd('ip address 192.168.10.1/24')
        dutA.cmd('interface vlan20')
        dutA.cmd('ip address 192.168.20.1/24')
        dutA.cmd('interface vlan30')
        dutA.cmd('ip vrf forwarding red')
        dutA.cmd('ip address 192.168.30.1/24')
        dutA.cmd('interface vlan40')
        dutA.cmd('ip vrf forwarding blue')
        dutA.cmd('ip address 192.168.40.1/24')

        # static ARP entries on the test port
        dutA.mode(')#')
        dutA.cmd('arp 192.168.10.201 0000.5e00.5301 {}'.format(portA.name))
        dutA.cmd('arp 192.168.10.202 0000.5e00.5302 {}'.format(portA.name))
        dutA.mode('#')

        # neighbour table for the Scapy responders on the test-port host: ip -> (mac, vlan)
        neighbours = {
            '192.168.10.11': ('00:00:5e:00:0a:11', 10),
            '192.168.10.12': ('00:00:5e:00:0a:12', 10),
            '192.168.10.13': ('00:00:5e:00:0a:13', 10),
            '192.168.10.14': ('00:00:5e:00:0a:14', 10),
            '192.168.30.11': ('00:00:5e:00:1e:11', 30),
            '192.168.30.12': ('00:00:5e:00:1e:12', 30),
            '192.168.40.11': ('00:00:5e:00:28:11', 40),
            '192.168.40.12': ('00:00:5e:00:28:12', 40),
        }
        self.arp_responder_stop = {'run': True}
        stopFlag = self.arp_responder_stop
        ifaceName = ethA.name

        def answer(pkt):
            if not pkt.haslayer(ARP) or pkt[ARP].op != 1:
                return
            entry = neighbours.get(pkt[ARP].pdst)
            if entry is None:
                return
            mac, vlan = entry
            reply = (Ether(src=mac, dst=pkt[ARP].hwsrc) / Dot1Q(vlan=vlan) /
                     ARP(op=2, hwsrc=mac, psrc=pkt[ARP].pdst, hwdst=pkt[ARP].hwsrc, pdst=pkt[ARP].psrc))
            sendp(reply, iface=ifaceName, verbose=False)

        def responder():
            while stopFlag['run']:
                sniff(iface=ifaceName, filter='arp', prn=answer, timeout=2, store=0)

        self.arp_responder_thread = Thread(target=responder)
        self.arp_responder_thread.daemon = True
        self.arp_responder_thread.start()

        self.suite_tcpdump = tb.start_tcpdump(ethA.name, 'arp_suite.pcap', 'arp or ip')

    def tear_down(self):
        tb = self.tb
        dutA = self.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        # One-time SUITE cleanup, runs ONCE after all cases. No pass/fail.
        if getattr(self, 'arp_responder_stop', None) is not None:
            self.arp_responder_stop['run'] = False
        if getattr(self, 'arp_responder_thread', None) is not None:
            self.arp_responder_thread.join(10)
        if getattr(self, 'suite_tcpdump', None) is not None:
            tb.stop_tcpdump(self.suite_tcpdump)

        dutA.mode(')#')
        dutA.cmd('no arp 192.168.10.201')
        dutA.cmd('no arp 192.168.10.202')
        dutA.cmd('interface vlan30')
        dutA.cmd('no ip address')
        dutA.cmd('no ip vrf forwarding')
        dutA.cmd('interface vlan40')
        dutA.cmd('no ip address')
        dutA.cmd('no ip vrf forwarding')
        dutA.cmd('interface vlan10')
        dutA.cmd('no ip address')
        dutA.cmd('interface vlan20')
        dutA.cmd('no ip address')
        dutA.cmd('interface {}'.format(portPeer.name))
        dutA.cmd('no switchport access vlan')
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('switchport trunk allowed vlan remove 10,30,40')
        dutA.cmd('no switchport trunk')
        dutA.cmd('switchport mode access')
        dutA.mode(')#')
        dutA.cmd('no interface vlan10')
        dutA.cmd('no interface vlan20')
        dutA.cmd('no interface vlan30')
        dutA.cmd('no interface vlan40')
        dutA.cmd('no ip vrf red')
        dutA.cmd('no ip vrf blue')
        dutA.cmd('vlan database')
        dutA.cmd('no vlan 10,20,30,40')
        dutA.cmd('exit')
        dutA.mode('#')


class TestCase_1(ATTestCase.TestCase):
    testCaseDesc = "From the DUT, ping 192.168.10.11, .12, .13 and .14 (2 packets each). Then read 'show arp' and save the full table."
    # ART identity <family>.<case>.<TestCase> — the framework composes the same triple
    # from the filename and this class name, and the run log prints it per case.
    testCaseRef = 'AWPTCM-T33247, 9002.33247.1'
    testCaseMethod = "From the DUT, ping 192.168.10.11, .12, .13 and .14 (2 packets each). Then read 'show arp' and save the full table.\n"
    testCaseMethod += "Verify: 'show arp' lists all four neighbours, each with the MAC its responder uses, on interface vlan10 and the test port, as dynamic entries. Both 192.168.10.201 (0000.5e00.5301) and 192.168.10.202 (0000.5e00.5302) are listed as static. Record the snapshot.\n"

    def configure(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        # Per-case PRECONDITIONS: the device state this step presumes, config only — no
        # pass/fail (main() verifies; tear_down() mirrors this in `no` form). Runs after
        # TestSet.configure() and after the previous case's tear_down(), so nothing another
        # case set up is still in effect here.
        dutA.mode('#')

    def main(self):
        # ART 1351_gratuitous_arp/test-1351.1001.py lines 287-362
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        self.log("STEP 4: From the DUT, ping 192.168.10.11, .12, .13 and .14 (2 packets each). Then read 'show arp' and save the full table.")
        neighbours = ['192.168.10.11', '192.168.10.12', '192.168.10.13', '192.168.10.14']
        statics = {'192.168.10.201': '0000.5e00.5301', '192.168.10.202': '0000.5e00.5302'}
        dutA.mode('#')
        for ip in neighbours:
            dutA.cmd('ping {} repeat 2 timeout 2'.format(ip))
        output = dutA.cmd('show arp')
        self.log('OBSERVED: {}'.format(output))

        # Parse the table: IP Address, LL Address, Interface, Port, Type
        table = {}
        for line in output.splitlines():
            tokens = line.split()
            if len(tokens) >= 5 and tokens[0].count('.') == 3:
                table[tokens[0]] = (tokens[1].lower(), tokens[2], tokens[3], tokens[4])

        if not table:
            publish_value(self, 'baselineArp', None)
            publish_value(self, 'baselineCount', None)
            self.failed('show arp returned no parsable ARP rows: {}'.format(output.strip()[:200]))
            return

        ok = True
        for ip in neighbours:
            entry = table.get(ip)
            if entry is None:
                ok = False
                self.failed('neighbour {} missing from show arp'.format(ip))
                continue
            mac, intf, port, etype = entry
            if intf != 'vlan10':
                ok = False
                self.failed('neighbour {} is on interface {}, expected vlan10'.format(ip, intf))
            elif port != portA.name:
                ok = False
                self.failed('neighbour {} is on port {}, expected {}'.format(ip, port, portA.name))
            elif etype != 'dynamic':
                ok = False
                self.failed('neighbour {} type is {}, expected dynamic'.format(ip, etype))
            elif mac == '0000.0000.0000':
                ok = False
                self.failed('neighbour {} has an empty MAC {}'.format(ip, mac))
            else:
                self.passed('neighbour {} is dynamic on vlan10/{} with MAC {}'.format(ip, port, mac))

        # each neighbour must have a distinct responder MAC
        macs = [table[ip][0] for ip in neighbours if ip in table]
        if len(set(macs)) != len(macs):
            ok = False
            self.failed('neighbour MACs are not unique: {}'.format(macs))

        for ip, expected in statics.items():
            entry = table.get(ip)
            if entry is None:
                ok = False
                self.failed('static entry {} missing from show arp'.format(ip))
            elif entry[0] != expected or entry[3] != 'static':
                ok = False
                self.failed('{} is MAC {} type {}, expected {} static'.format(ip, entry[0], entry[3], expected))
            else:
                self.passed('static entry {} present with MAC {}'.format(ip, entry[0]))

        if ok:
            publish_value(self, 'baselineArp', dict(table))
            publish_value(self, 'baselineCount', len(table))
